import{_ as i,a0 as l,w as o,s as r,I as a,x as n,a1 as e,A as t,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const q=JSON.parse('{"title":"使用 RT-Thread 的 FinSH 對硬件進行編程 | LCTT x X-CMD","titleTemplate":false,"description":"使用 RT-Thread 的 FinSH 對硬件進行編程 | LCTT (202009) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 RT-Thread 的 FinSH 對硬件進行編程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 RT-Thread 的 FinSH 對硬件進行編程 | LCTT (202009) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202009/20200907 Program hardware from the Linux command line","title":"使用 RT-Thread 的 FinSH 對硬件進行編程","tag":"202009","desc":""},"relativePath":"202009/20200907 Program hardware from the Linux command line.md","filePath":"[post].md"}'),c={name:"202009/20200907 Program hardware from the Linux command line.md"};function u(h,s,g,k,m,f){const p=l("Link");return o(),r("div",null,[s[20]||(s[20]=a("h1",{id:"使用-rt-thread-的-finsh-對硬件進行編程",tabindex:"-1"},[n("使用 RT-Thread 的 FinSH 對硬件進行編程 "),a("a",{class:"header-anchor",href:"#使用-rt-thread-的-finsh-對硬件進行編程","aria-label":"Permalink to “使用 RT-Thread 的 FinSH 對硬件進行編程”"},"​")],-1)),s[21]||(s[21]=a("blockquote",null,[a("p",null,"由於物聯網（IoT）的興起，對硬件進行編程變得越來越普遍。RT-Thread 可以讓你可以用 FinSH 從 Linux 命令列與設備進行溝通、")],-1)),s[22]||(s[22]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202009/29/233059w523g55qzvo53h6i.jpg",alt:""})],-1)),a("p",null,[s[2]||(s[2]=n("RT-Thread 是一個開源的",-1)),e(p,{href:"https://opensource.com/article/20/6/open-source-rtos"},{default:t(()=>[...s[0]||(s[0]=[n("實時操作系統",-1)])]),_:1}),s[3]||(s[3]=n("，用於對物聯網（IoT）設備進行編程。FinSH 是 ",-1)),e(p,{href:"https://github.com/RT-Thread/rt-thread"},{default:t(()=>[...s[1]||(s[1]=[n("RT-Thread",-1)])]),_:1}),s[4]||(s[4]=n(" 的命令列組件，它提供了一套操作界面，使用户可以從命令列與設備進行溝通。它主要用於調試或查看系統信息。",-1))]),s[23]||(s[23]=d(`<p>通常情況下，開發調試使用硬件調試器和 <code>printf</code> 日誌來顯示。但在某些情況下，這兩種方法並不是很有用，因為它是從運行的內容中抽象出來的，而且它們可能很難解析。不過 RT-Thread 是一個多線程系統，當你想知道一個正在運行的線程的狀態，或者手動控制系統的當前狀態時，這很有幫助。因為它是多線程的，所以你能夠擁有一個交互式的 shell，你可以直接在設備上輸入命令、調用函數來獲取你需要的信息，或者控制程序的行為。如果你只習慣於 Linux 或 BSD 等現代操作系統，這在你看來可能很普通，但對於硬件黑客來説，這是極其奢侈的，遠超將串行電纜直接連線到電路板上以獲取一絲錯誤的做法。</p><p>FinSH 有兩種模式。</p><ul><li>C 語言解釋器模式，稱為 c-style。</li><li>傳統的命令列模式，稱為 msh（模組 shell）。</li></ul><p>在 C 語言解釋器模式下，FinSH 可以解析執行大部分 C 語言的表達式，並使用函數調用訪問系統上的函數和全局變量。它還可以從命令列創建變量。</p><p>在 msh 模式下，FinSH 的操作與 Bash 等傳統 shell 類似。</p><h3 id="gnu-命令標準" tabindex="-1">GNU 命令標準 <a class="header-anchor" href="#gnu-命令標準" aria-label="Permalink to “GNU 命令標準”">​</a></h3><p>當我們在開發 FinSH 時，我們瞭解到，在編寫命令列應用程序之前，你需要熟悉 GNU 命令列標準。這個標準實踐的框架有助於給界面帶入熟悉感，這有助於開發人員在使用時感到舒適和高效。</p><p>一個完整的 GNU 命令主要由四個部分組成。</p><ol><li>命令名（可執行文件）：命令列程序的名稱；</li><li>子命令：命令程序的子函數名稱。</li><li>選項：子命令函數的配置選項。</li><li>參數：子命令函數配置選項的相應參數。</li></ol><p>你可以在任何命令中看到這一點。以 Git 為例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git reset --hard HEAD~1</span></span></code></pre></div><p>這一點可以分解為：</p><p><img src="https://opensource.com/sites/default/files/uploads/command-line-apps_2.png" alt="GNU command line standards" title="GNU command line standards"></p><p>可執行的命令是 <code>git</code>，子命令是 <code>reset</code>，使用的選項是 <code>--head</code>，參數是 <code>HEAD~1</code>。</p><p>再舉個例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl enable --now firewalld</span></span></code></pre></div><p>可執行的命令是 <code>systemctl</code>，子命令是 <code>enable</code>，選項是 <code>--now</code>，參數是 <code>firewalld</code>。</p><p>想像一下，你想用 RT-Thread 編寫一個符合 GNU 標準的命令列程序。FinSH 擁有你所需要的一切，並且會按照預期運行你的代碼。更棒的是，你可以依靠這種合規性，讓你可以自信地移植你最喜歡的 Linux 程序。</p><h3 id="編寫一個優雅的命令列程序" tabindex="-1">編寫一個優雅的命令列程序 <a class="header-anchor" href="#編寫一個優雅的命令列程序" aria-label="Permalink to “編寫一個優雅的命令列程序”">​</a></h3><p>下面是一個 RT-Thread 運行命令的例子，RT-Thread 開發人員每天都在使用這個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>usage: env.py package [-h] [--force-update] [--update] [--list] [--wizard]</span></span>
<span class="line"><span>                      [--upgrade] [--printenv]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>optional arguments:</span></span>
<span class="line"><span>  -h, --help      show this help message and exit</span></span>
<span class="line"><span>  --force-update  force update and clean packages, install or remove the</span></span>
<span class="line"><span>                  packages by your settings in menuconfig</span></span>
<span class="line"><span>  --update        update packages, install or remove the packages by your</span></span>
<span class="line"><span>                  settings in menuconfig</span></span>
<span class="line"><span>  --list          list target packages</span></span>
<span class="line"><span>  --wizard        create a new package with wizard</span></span>
<span class="line"><span>  --upgrade       upgrade local packages list and ENV scripts from git repo</span></span>
<span class="line"><span>  --printenv      print environmental variables to check</span></span></code></pre></div><p>正如你所看到的那樣，它看起來很熟悉，行為就像你可能已經在 Linux 或 BSD 上運行的大多數 POSIX 應用程序一樣。當使用不正確或不充分的語法時，它會提供幫助，它支持長選項和短選項。這種通用的用户界面對於任何使用過 Unix 終端的人來説都是熟悉的。</p><h3 id="選項種類" tabindex="-1">選項種類 <a class="header-anchor" href="#選項種類" aria-label="Permalink to “選項種類”">​</a></h3><p>選項的種類很多，按長短可分為兩大類。</p><ol><li>短選項：由一個連字符加一個字母組成，如 <code>pkgs -h</code> 中的 <code>-h</code> 選項。</li><li>長選項：由兩個連字符加上單詞或字母組成，例如，<code>scons- --target-mdk5</code> 中的 <code>--target</code> 選項。</li></ol><p>你可以把這些選項分為三類，由它們是否有參數來決定。</p><ol><li>沒有參數：該選項後面不能有參數。</li><li>參數必選：選項後面必須有參數。</li><li>參數可選：選項後可以有參數，但不是必需的。</li></ol><p>正如你對大多數 Linux 命令的期望，FinSH 的選項解析非常靈活。它可以根據空格或等號作為定界符來區分一個選項和一個參數，或者僅僅通過提取選項本身並假設後面的內容是參數（換句話説，完全沒有定界符）。</p><ul><li><code>wavplay -v 50</code></li><li><code>wavplay -v50</code></li><li><code>wavplay --vol=50</code></li></ul><h3 id="使用-optparse" tabindex="-1">使用 optparse <a class="header-anchor" href="#使用-optparse" aria-label="Permalink to “使用 optparse”">​</a></h3><p>如果你曾經寫過命令列程序，你可能會知道，一般來説，你所選擇的語言有一個叫做 optparse 的庫或模組。它是提供給程序員的，所以作為命令的一部分輸入的選項（比如 <code>-v</code> 或 <code>--verbose</code>）可以與命令的其他部分進行<em>解析</em>。這可以幫助你的代碼從一個子命令或參數中獲取一個選項。</p><p>當為 FinSH 編寫一個命令時，<code>optparse</code> 包希望使用這種格式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MSH_CMD_EXPORT_ALIAS(pkgs, pkgs, this is test cmd.);</span></span></code></pre></div><p>你可以使用長形式或短形式，或者同時使用兩種形式來實現選項。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>static struct optparse_long long_opts[] =</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    {&quot;help&quot;        , &#39;h&#39;, OPTPARSE_NONE}, // Long command: help, corresponding to short command h, without arguments.</span></span>
<span class="line"><span>    {&quot;force-update&quot;,  0 , OPTPARSE_NONE}, // Long comman: force-update, without arguments</span></span>
<span class="line"><span>    {&quot;update&quot;      ,  0 , OPTPARSE_NONE},</span></span>
<span class="line"><span>    {&quot;list&quot;        ,  0 , OPTPARSE_NONE},</span></span>
<span class="line"><span>    {&quot;wizard&quot;      ,  0 , OPTPARSE_NONE},</span></span>
<span class="line"><span>    {&quot;upgrade&quot;     ,  0 , OPTPARSE_NONE},</span></span>
<span class="line"><span>    {&quot;printenv&quot;    ,  0 , OPTPARSE_NONE},</span></span>
<span class="line"><span>    { NULL         ,  0 , OPTPARSE_NONE}</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>創建完選項後，寫出每個選項及其參數的命令和説明：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>static void usage(void)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    rt_kprintf(&quot;usage: env.py package [-h] [--force-update] [--update] [--list] [--wizard]\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;                      [--upgrade] [--printenv]\\n\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;optional arguments:\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;  -h, --help      show this help message and exit\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;  --force-update  force update and clean packages, install or remove the\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;                  packages by your settings in menuconfig\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;  --update        update packages, install or remove the packages by your\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;                  settings in menuconfig\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;  --list          list target packages\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;  --wizard        create a new package with wizard\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;  --upgrade       upgrade local packages list and ENV scripts from git repo\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;  --printenv      print environmental variables to check\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>下一步是解析。雖然你還沒有實現它的功能，但解析後的代碼框架是一樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>int pkgs(int argc, char **argv)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    int ch;</span></span>
<span class="line"><span>    int option_index;</span></span>
<span class="line"><span>    struct optparse options;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if(argc == 1)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        usage();</span></span>
<span class="line"><span>        return RT_EOK;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    optparse_init(&amp;options, argv);</span></span>
<span class="line"><span>    while((ch = optparse_long(&amp;options, long_opts, &amp;option_index)) != -1)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        ch = ch;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        rt_kprintf(&quot;\\n&quot;);</span></span>
<span class="line"><span>        rt_kprintf(&quot;optopt = %c\\n&quot;, options.optopt);</span></span>
<span class="line"><span>        rt_kprintf(&quot;optarg = %s\\n&quot;, options.optarg);</span></span>
<span class="line"><span>        rt_kprintf(&quot;optind = %d\\n&quot;, options.optind);</span></span>
<span class="line"><span>        rt_kprintf(&quot;option_index = %d\\n&quot;, option_index);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    rt_kprintf(&quot;\\n&quot;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    return RT_EOK;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>這裏是函數頭文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include &quot;optparse.h&quot;</span></span>
<span class="line"><span>#include &quot;finsh.h&quot;</span></span></code></pre></div><p>然後，編譯並下載到設備上。</p><p><img src="https://opensource.com/sites/default/files/uploads/command-line-apps_3.png" alt="Output" title="Output"></p><h3 id="硬件黑客" tabindex="-1">硬件黑客 <a class="header-anchor" href="#硬件黑客" aria-label="Permalink to “硬件黑客”">​</a></h3><p>對硬件進行編程似乎很嚇人，但隨着物聯網的發展，它變得越來越普遍。並不是所有的東西都可以或者應該在樹莓派上運行，但在 RT-Thread，FinSH 可以讓你保持熟悉的 Linux 感覺。</p><p>如果你對在裸機上編碼感到好奇，不妨試試 RT-Thread。</p><hr>`,47)),a("p",null,[s[6]||(s[6]=n("via: ",-1)),e(p,{href:"https://opensource.com/article/20/9/hardware-command-line"},{default:t(()=>[...s[5]||(s[5]=[n("https://opensource.com/article/20/9/hardware-command-line",-1)])]),_:1})]),a("p",null,[s[11]||(s[11]=n("作者：",-1)),e(p,{href:"https://opensource.com/users/alansmithee"},{default:t(()=>[...s[7]||(s[7]=[n("Alan Smithee",-1)])]),_:1}),s[12]||(s[12]=n(" 選題：",-1)),e(p,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[8]||(s[8]=[n("lujun9972",-1)])]),_:1}),s[13]||(s[13]=n(" 譯者：",-1)),e(p,{href:"https://github.com/wxy"},{default:t(()=>[...s[9]||(s[9]=[n("wxy",-1)])]),_:1}),s[14]||(s[14]=n(" 校對：",-1)),e(p,{href:"https://github.com/wxy"},{default:t(()=>[...s[10]||(s[10]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[17]||(s[17]=n("本文由 ",-1)),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[15]||(s[15]=[n("LCTT",-1)])]),_:1}),s[18]||(s[18]=n(" 原創編譯，",-1)),e(p,{href:"https://linux.cn/"},{default:t(()=>[...s[16]||(s[16]=[n("Linux中國",-1)])]),_:1}),s[19]||(s[19]=n(" 榮譽推出",-1))])])}const v=i(c,[["render",u]]);export{q as __pageData,v as default};
